B.Tu=new A.fS("Za jednou vesnic\xed roste velk\xfd les, kter\xfd nezn\xe1 \u017e\xe1dn\xfd nudn\xfd dosp\u011bl\xe1k. V n\u011bm stoj\xed star\xe1 vrba s tajnou klubovnou uvnit\u0159 kmene. Dnes se k n\xed poprv\xe9 bl\xed\u017e\xed\u0161 i ty. A to zrovna v den, kdy maj\xed str\xe1\u017eci stolet\xe9 narozeniny.")
B.a_r=new A.C(45,40)
B.b4=new A.tD("marek","assets/images/stories/forest_rangers/portrait_marek.svg",B.a_r)
B.O2=s(["\u201eSt\u016fj! Dovnit\u0159 sm\xed jen ten, kdo zn\xe1 tajn\xfd pozdrav.\u201c"],t.s)
B.a0j=new A.bw(B.b4,B.O2)
B.a_s=new A.C(46,40)
B.az=new A.tD("karel","assets/images/stories/forest_rangers/portrait_karel.svg",B.a_s)
B.P3=s(["\u201eChce\u0161 se k n\xe1m p\u0159idat? M\xe1\u0161 dobr\xfd post\u0159eh?\u201c"],t.s)
B.a06=new A.bw(B.az,B.P3)
B.QR=s([B.Tu,B.a0j,B.a06],t.GD)
B.a1_=new A.fV("story_00_intro",B.QR)
B.To=new A.fS("Dve\u0159e se otev\u0159ou do tmy a ty vstoup\xed\u0161 dovnit\u0159. Klubovna von\xed d\u0159evem a star\xfdm pap\xedrem. Uprost\u0159ed stoj\xed st\u016fl a na n\u011bm le\u017e\xed podivn\xfd den\xedk.")
B.Oh=s(["\u201eDve\u0159e se otev\u0159ely, tak\u017ee pozdrav u\u017e zn\xe1\u0161. J\xe1 se jmenuji Marek, tamto byl Karel a tohle je Tereza. Poj\u010f d\xe1l.\u201c"],t.s)
B.a04=new A.bw(B.b4,B.Oh)
B.Tw=new A.fS("Za dve\u0159mi se ozve hlasit\xe9 \u017euchnut\xed.")
B.Oo=s(["\u201eJsem v po\u0159\xe1dku! Spadl jsem schv\xe1ln\u011b, abych prolomil ledy.\u201c"],t.s)
B.a0q=new A.bw(B.az,B.Oo)
B.a_w=new A.C(56,59)
B.bb=new A.tD("tereza","assets/images/stories/forest_rangers/portrait_tereza.svg",B.a_w)
B.Qt=s(["\u201eMarku! N\xe1\u0161 den\xedk nejde otev\u0159\xedt.\u201c","\u201eV\u010dera ve\u010der ho omotala divok\xe1 li\xe1na.\u201c","\u201eZkou\u0161eli jsme ji odmotat, ale li\xe1na dr\u017e\xed jako p\u0159ilepen\xe1.\u201c"],t.s)
B.a0h=new A.bw(B.bb,B.Qt)
B.Or=s(["\u201eBez den\xedku nem\u016f\u017eeme d\u011blat pr\u016fzkum lesa.\u201c"],t.s)
B.a00=new A.bw(B.b4,B.Or)
B.On=s([B.To,B.a04,B.Tw,B.a0q,B.a0h,B.a00],t.GD)
B.a14=new A.fV("story_01a_clubhouse_arrival",B.On)
B.OG=s(["\u201eA dneska to pot\u0159ebujeme v\xedc ne\u017e kdy jindy! Klub m\xe1 st\xe9 narozeniny.\u201c"],t.s)
B.a0r=new A.bw(B.b4,B.OG)
B.P6=s(["\u201ePodle legendy se pr\xe1v\u011b dnes d\xe1 naj\xedt to, co po sob\u011b zakladatel\xe9 nechali. Jen\u017ee jen do z\xe1padu slunce.\u201c"],t.s)
B.a0b=new A.bw(B.bb,B.P6)
B.Ny=s(["\u201ePoklad! T\u0159eba jedl\xfd poklad. Dort! Ur\u010dit\u011b to bude dort.\u201c"],t.s)
B.a_Y=new A.bw(B.az,B.Ny)
B.Om=s(["\u201eNikdo ne\u0159ekl poklad.\u201c"],t.s)
B.a0_=new A.bw(B.bb,B.Om)
B.O3=s(["\u201eNikdo ne\u0159ekl, \u017ee nen\xed.\u201c"],t.s)
B.a0u=new A.bw(B.az,B.O3)
B.N3=s(["\u201eCokoliv to je, najdeme to. Dal\u0161\xed \u0161ance p\u0159ijde a\u017e za sto let.\u201c"],t.s)
B.a0o=new A.bw(B.b4,B.N3)
B.PJ=s(["\u201eTo bych ten dort nestihl ochutnat.\u201c"],t.s)
B.a_S=new A.bw(B.az,B.PJ)
B.PI=s([B.a0r,B.a0b,B.a_Y,B.a0_,B.a0u,B.a0o,B.a_S],t.GD)
B.a12=new A.fV("story_01b_legend_and_time",B.PI)
B.Ty=new A.fS("Li\xe1na povol\xed, den\xedk se otev\u0159e a vypadne z n\u011bj hrom\xe1dka pap\xedrov\xfdch \xfatr\u017ek\u016f.")
B.OI=s(["\u201eTo je star\xe1 mapa lesa!\u201c"],t.s)
B.a01=new A.bw(B.az,B.OI)
B.Oz=s(["\u201eAle ne, n\u011bkdo ji roztrhal. Karle?\u201c"],t.s)
B.a08=new A.bw(B.bb,B.Oz)
B.QF=s(["\u201eJ\xe1 to nebyl. \u2026 Asi.\u201c"],t.s)
B.a09=new A.bw(B.az,B.QF)
B.PB=s(["\u201ePap\xedr je star\u0161\xed ne\u017e na\u0161e babi\u010dky. Tenhle se roztrhne i s\xe1m.\u201c"],t.s)
B.a_T=new A.bw(B.bb,B.PB)
B.NW=s(["\u201eDob\u0159e. Co te\u010f s t\xedm?\u201c"],t.s)
B.a_X=new A.bw(B.b4,B.NW)
B.OK=s([B.Ty,B.a01,B.a08,B.a09,B.a_T,B.a_X],t.GD)
B.a0X=new A.fV("story_02_torn_map",B.OK)
B.Nz=s(["\u201eKoukejte! To je cesta zakladatel\u016f klubu.\u201c"],t.s)
B.a_R=new A.bw(B.b4,B.Nz)
B.Q2=s(["\u201eCo kdybychom se za\u0161li pod\xedvat, odkud k n\xe1m zakladatel\xe9 p\u0159i\u0161li?\u201c"],t.s)
B.a0v=new A.bw(B.az,B.Q2)
B.Tr=new A.fS("\u010cerven\xe1 \u010d\xe1ra na map\u011b vede hluboko do lesa. Stoj\xedte p\u0159ed cestou z kamen\u016f, kterou blokuje trn\xed.")
B.Qu=s(["\u201eCesta z mapy vede p\u0159\xedmo tudy.\u201c"],t.s)
B.a0x=new A.bw(B.bb,B.Qu)
B.QB=s(["\u201eJ\xe1 p\u0159es ty kameny a trn\xed nejdu, Terko.\u201c"],t.s)
B.a_U=new A.bw(B.az,B.QB)
B.Ps=s(["\u201eNikdo ne\u0159ekl, \u017ee to bude snadn\xe9, K\xe1jo. Tak poj\u010f.\u201c","\u201eZa mnou! Str\xe1\u017eci se n\u011bjak\xe9ho trn\xed neboj\xed.\u201c"],t.s)
B.a_O=new A.bw(B.b4,B.Ps)
B.NN=s(["\u201eStr\xe1\u017eci se neboj\xed, ale bod\xe1 to \xfapln\u011b stejn\u011b jako do kohokoli jin\xe9ho.\u201c"],t.s)
B.a05=new A.bw(B.az,B.NN)
B.OE=s([B.a_R,B.a0v,B.Tr,B.a0x,B.a_U,B.a_O,B.a05],t.GD)
B.a11=new A.fV("story_03_founders_trail",B.OE)
B.Tp=new A.fS("Trn\xed se rozestoup\xed a dovol\xed v\xe1m proj\xedt d\xe1l. Na m\xfdtin\u011b s m\u011bkk\xfdm bahnem jsou jemn\xe9 otisky kv\u011btin.")
B.Ov=s(["\u201eKdo by v\xe1lel kv\u011btiny v bahn\u011b?\u201c"],t.s)
B.a_Q=new A.bw(B.az,B.Ov)
B.PH=s(["\u201eZakladatel\xe9 klubu takto zna\u010dili cestu.\u201c","\u201eAle ne! Vypad\xe1 to, \u017ee je n\u011bkdo odnesl.\u201c"],t.s)
B.a0m=new A.bw(B.bb,B.PH)
B.Qq=s(["\u201eA co s t\xedm te\u010f budeme d\u011blat? J\xe1 u\u017e m\xe1m bahno po kotn\xedky!\u201c"],t.s)
B.a0l=new A.bw(B.az,B.Qq)
B.OL=s(["\u201ePod\xedv\xe1me se kolem, jestli n\u011bjak\xe9 nenajdeme.\u201c"],t.s)
B.a_N=new A.bw(B.b4,B.OL)
B.Qs=s([B.Tp,B.a_Q,B.a0m,B.a0l,B.a_N],t.GD)
B.a15=new A.fV("story_04_flowers_in_mud",B.Qs)
B.Tt=new A.fS("Posledn\xed kv\u011btina zapadne na sv\xe9 m\xedsto a cel\xe1 m\xfdtina rozkvete. Mezi kv\u011bty se objev\xed \xfazk\xe1 p\u011b\u0161inka, kter\xe1 kon\u010d\xed u mohutn\xe9ho dubu.")
B.Oa=s(["\u201eTen dub je ur\u010dit\u011b star\u0161\xed ne\u017e my v\u0161ichni dohromady.\u201c"],t.s)
B.a0d=new A.bw(B.az,B.Oa)
B.N5=s(["\u201ePodle kmene m\xe1 aspo\u0148 p\u011bt set let.\u201c","\u201eHele veverka a vypad\xe1, \u017ee n\u011bco hl\xedd\xe1.\u201c"],t.s)
B.a_Z=new A.bw(B.bb,B.N5)
B.OX=s(["\u201eKouk\xe1 na m\u011b n\u011bjak hladov\u011b.\u201c"],t.s)
B.a02=new A.bw(B.az,B.OX)
B.QQ=s(["\u201ePoj\u010fme se pod\xedvat bl\xed\u017e.\u201c"],t.s)
B.a0i=new A.bw(B.b4,B.QQ)
B.Px=s([B.Tt,B.a0d,B.a_Z,B.a02,B.a0i],t.GD)
B.a0Z=new A.fV("story_05_old_oak",B.Px)
B.Ts=new A.fS("\u017daludy zmiz\xed v dutin\u011b dubu. Star\xfd dub se rozz\xe1\u0159\xed tepl\xfdm sv\u011btlem a zlat\xe1 z\xe1\u0159e miz\xed v d\xe1lce.")
B.Q3=s(["\u201eCo se to stalo?\u201c"],t.s)
B.a0w=new A.bw(B.az,B.Q3)
B.OW=s(["\u201eVypad\xe1 to, jako bychom n\u011bco probudili.\u201c"],t.s)
B.a_V=new A.bw(B.b4,B.OW)
B.Oe=s(["\u201ePros\xedm, a\u0165 je to n\u011bco roztomil\xe9ho.\u201c"],t.s)
B.a0t=new A.bw(B.az,B.Oe)
B.P5=s(["\u201eZa sv\u011btlem! Dub n\xe1m ukazuje cestu.\u201c"],t.s)
B.a_P=new A.bw(B.b4,B.P5)
B.Tq=new A.fS("Jdete sm\u011brem k z\xe1\u0159i. Zlat\xe9 sv\u011btlo v\xe1s dovede a\u017e k vodop\xe1du, kde ve skaln\xedm v\xfdklenku le\u017e\xed star\xe1 truhla.")
B.OZ=s(["\u201eTakovou truhlu jsem je\u0161t\u011b nevid\u011bla.\u201c"],t.s)
B.a0c=new A.bw(B.bb,B.OZ)
B.Qf=s([B.Ts,B.a0w,B.a_V,B.a0t,B.a_P,B.Tq,B.a0c],t.GD)
B.a0Y=new A.fV("story_06_waterfall_chest",B.Qf)
B.Tv=new A.fS("V\xedko se zvedne. Uvnit\u0159 le\u017e\xed svitek p\u0159ev\xe1zan\xfd prov\xe1zkem.")
B.OA=s(["\u201eSlunce u\u017e se dot\xfdk\xe1 korun strom\u016f!\u201c"],t.s)
B.a0f=new A.bw(B.bb,B.OA)
B.QJ=s(["\u201eHonem zp\u011bt do klubovny!\u201c","\u201eNev\xedme, co ten svitek skr\xfdv\xe1. Mus\xedme b\xfdt opatrn\xed.\u201c"],t.s)
B.a0p=new A.bw(B.b4,B.QJ)
B.Tx=new A.fS("Po n\xe1vratu do klubovny otev\u0159e\u0161 svitek. Sotva ho rozvine\u0161, vyl\xe9tnou z n\u011bj velk\xe9 bubliny.")
B.O7=s([B.Tv,B.a0f,B.a0p,B.Tx],t.GD)
B.a13=new A.fV("story_07_scroll",B.O7)
B.Tn=new A.fS("Posledn\xed paprsek slunce dopadne na svitek a klubovna se rozsv\xedt\xed lucernami.")
B.Qp=s(["\u201eTo je v\u0161echno? J\xe1 \u010dekal poklad.\u201c"],t.s)
B.a0e=new A.bw(B.az,B.Qp)
B.Qb=s(["\u201eCel\xe1 ta cesta byla zkou\u0161ka, K\xe1jo. Cht\u011bli zjistit, jestli m\xe1me trp\u011blivost.\u201c"],t.s)
